const run=$json;
// Use the template captured before research, never a newer template from the branch.
const finalHtml=render(run,$('Build Research Prompt').first().json.dashboardTemplate,true);
const {reviewHtml,commit,...audit}=run;
const draftPath=`runs/${run.runId}/review.html`;
const auditPath=`runs/${run.runId}/evidence.json`;
return [{json:{...run,finalHtml,audit,draftPath,auditPath,
  draftPagesUrl:`https://${run.owner}.github.io/${run.repo}/${draftPath}`,
  archiveBody:{message:`Briefing draft ${run.runId}`,branch:run.branch,content:Buffer.from(finalHtml).toString('base64')},
  auditBody:{message:`Evidence and human decisions ${run.runId}`,branch:run.branch,content:Buffer.from(JSON.stringify(audit,null,2)).toString('base64')}}}];

// review.html is a convenient latest-draft pointer. Approval refers to the immutable per-run draft.
if(![200,404].includes($json.statusCode)) throw new Error('Cannot read current review.html. Refusing overwrite.');
const run=$('Render Reviewed Dashboard').first().json;
const body={...run.archiveBody};
if($json.statusCode===200) body.sha=$json.body.sha;
return [{json:{url:run.api+'review.html',body}}];

const run=$('Render Reviewed Dashboard').first().json;
const form=$json.body??$json;
if(!['Approve','Reject'].includes(form.Decision)) throw new Error('An explicit publication decision is required.');
if(typeof form.Approver!=='string' || !form.Approver.trim()) throw new Error('Approver name is required.');
const saved=$('Archive Reviewed Draft').first().json.body;
if(!saved?.commit?.sha || !saved?.content?.sha) throw new Error('Draft commit identity missing.');
const decision={runId:run.runId,decision:form.Decision,approver:form.Approver.trim(),notes:form.Notes||'',at:new Date().toISOString(),draftPath:run.draftPath,draftCommit:saved.commit.sha,draftBlob:saved.content.sha,sourceRevision:run.sourceRevision,workflowBuild:run.workflowBuild};
return [{json:{...decision,approved:form.Decision==='Approve',api:run.api,branch:run.branch,
  body:{message:`Publication ${form.Decision.toLowerCase()} ${run.runId}`,branch:run.branch,content:Buffer.from(JSON.stringify(decision,null,2)).toString('base64')}}}];

// Publish bytes fetched from the EXACT approved commit, not the moving review.html pointer.
const current=$json;
const approved=$('Fetch Approved Review').first().json;
const decision=$('Record Publication Decision').first().json;
const run=$('Render Reviewed Dashboard').first().json;
if(!decision.approved) throw new Error('Publication was not approved.');
if(![200,404].includes(current.statusCode)) throw new Error('Cannot read current index.html. Refusing overwrite.');
if(approved.statusCode!==200 || approved.body.sha!==decision.draftBlob || approved.body.encoding!=='base64') throw new Error('Approved draft identity mismatch.');
const content=approved.body.content.replace(/\s/g,'');
if(content!==run.archiveBody.content) throw new Error('Approved draft content differs from reviewed bytes.');
const body={message:`Publish approved briefing ${run.runId}`,branch:run.branch,content};
if(current.statusCode===200) body.sha=current.body.sha;
return [{json:{url:run.api+'index.html',body}}];

const run=$('Render Reviewed Dashboard').first().json;
return [{json:{status:'Published approved briefing',runId:run.runId,
  sourceRevision:run.sourceRevision,publicationCommit:$json.body.commit.sha,
  dashboard:`https://${run.owner}.github.io/${run.repo}/`,
  archive:`https://${run.owner}.github.io/${run.repo}/${run.draftPath}`,
